  put(g, t, x, y, z, B.stairs("smooth_quartz", "north", "bottom"));
  put(g, t, x + 1, y, z, B.stairs("smooth_quartz", "north", "bottom"));
  put(g, t, x, y, z + 2, B.block("cauldron"));
  put(g, t, x + 1, y, z + 2, B.stairs("smooth_quartz", "south", "bottom"));
  return t;
}
